const $=id=>document.getElementById(id), today=()=>new Date().toISOString().slice(0,10), rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0), uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
