initDatabase().then(async status=>{ $('dbStatus').textContent=status; const note=document.querySelector('#settings .settings-grid > div:nth-child(2) .muted'); if(note) note.textContent=isNative?'Data tersimpan di SQLite pada memori internal HP (privat aplikasi), tanpa memerlukan internet.':'Data tersimpan di IndexedDB browser pada perangkat ini.'; await seedSettings(); await refreshAll(); }).catch(err=>{console.error('Inisialisasi database gagal:',err);$('dbStatus').textContent='Database gagal dibuka';toast('Database tidak tersedia: '+err.message)});
async function seedSettings(){let s=await all('settings');if(!s.length)await put('settings',{id:'main',name:'Usaha Saya',address:'',phone:'',currency:'IDR',footer:'Terima kasih telah berbelanja'});loadSettings()}
async function loadSettings(){let s=(await all('settings'))[0];if(!s)return;$('storeLabel').textContent=s.name;$('storeName').value=s.name;$('storeAddress').value=s.address||'';$('storePhone').value=s.phone||'';$('receiptFooter').value=s.footer||'';if(s.logo){$('logoPreview').src=s.logo;$('logoPreview').style.display='block'}else{$('logoPreview').style.display='none'};$('currency').value=s.currency||'IDR'}
async function refreshAll(){await renderDashboard();await renderProducts();await renderPOS();await renderHistory();await renderExpenses();await renderReports();await renderEmployees();await renderCategoryMaster();await renderStock();await renderAssets();await renderDebts();await loadSettings()}
function showPage(id){if(['reports','settings','assets','debts'].includes(id)){requestProtectedPage(id);return}document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id));if(id==='reports')renderReports();if(id==='customers')renderCustomers();if(id==='expenses')renderExpenses();if(id==='stock')renderStock()}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function toast(s){let t=$('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function table(rows,headers){if(!rows.length)return '<div class="empty">Belum ada data.</div>';return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
async function renderDashboard(){let tx=await all('transactions'),ex=await all('expenses'),ps=await all('products'),d=today(),todayTx=tx.filter(x=>x.date===d),todayEx=ex.filter(x=>x.date===d);profitValue=rupiah(todayTx.reduce((a,x)=>a+x.items.reduce((b,i)=>b+((Number(i.price)||0)-(Number(i.costPrice)||0))*(Number(i.qty)||0),0),0)-todayEx.reduce((a,x)=>a+(Number(x.amount)||0),0));if($('todayProfit'))$('todayProfit').textContent='••••••';$('todaySales').textContent=rupiah(todayTx.reduce((a,x)=>a+x.total,0));$('todayCount').textContent=todayTx.length+' transaksi';$('todayTx').textContent=todayTx.length;$('todayExpense').textContent=rupiah(todayEx.reduce((a,x)=>a+x.amount,0));if($('productCount'))$('productCount').textContent=ps.length;$('recentTable').innerHTML=table(tx.sort((a,b)=>b.createdAt-a.createdAt).slice(0,5).map(x=>`<tr><td>${x.invoice}</td><td>${x.date}</td><td>${x.type}</td><td>${x.payment}</td><td><b>${rupiah(x.total)}</b></td><td><button class="link" onclick="showDetail('${x.id}')">Detail</button></td></tr>`),['No. Nota','Tanggal','Tipe','Pembayaran','Total','']);}

// Master kategori produk; legacy text categories are migrated by db.js.
async function renderCategoryMaster(){
 const cats=(await all('categories')).sort((x,y)=>x.name.localeCompare(y.name,'id'));
 $('categoryTable').innerHTML=table(cats.map(c=>`<tr><td>${esc(c.name)}</td><td><button class="link" onclick="editCategory('${c.id}')">Edit</button> <button class="link" onclick="deleteCategory('${c.id}')">Hapus</button></td></tr>`),['Kategori','Aksi']);
 const opts=cats.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('');
 $('pCategory').innerHTML='<option value="">Pilih kategori</option>'+opts;
}
$('manageCategories').onclick=async()=>{if(!await requirePin('mengelola kategori produk'))return;$('categoryForm').reset();$('categoryId').value='';await renderCategoryMaster();$('categoryDialog').showModal()};
$('saveCategory').onclick=async e=>{e.preventDefault();const name=$('categoryName').value.trim();if(!name)return;const cats=await all('categories');if(cats.some(c=>c.name.toLocaleLowerCase('id-ID')===name.toLocaleLowerCase('id-ID')&&c.id!==$('categoryId').value))return toast('Kategori sudah ada');const id=$('categoryId').value||name.toLocaleLowerCase('id-ID').replace(/[^a-z0-9]+/g,'-');await put('categories',{id,name,updatedAt:Date.now()});$('categoryName').value='';$('categoryId').value='';await renderCategoryMaster();await renderProducts();toast('Kategori disimpan')};
window.editCategory=async id=>{if(!await requirePin('mengubah kategori'))return;const c=(await all('categories')).find(x=>x.id===id);if(c){$('categoryId').value=c.id;$('categoryName').value=c.name}};
window.deleteCategory=async id=>{if(!await requirePin('menghapus kategori'))return;const c=(await all('categories')).find(x=>x.id===id);if(!c)return;const used=(await all('products')).some(p=>(p.category||'Umum').toLocaleLowerCase('id-ID')===c.name.toLocaleLowerCase('id-ID'));if(used)return toast('Kategori masih digunakan produk. Ubah kategori produk terlebih dahulu.');if(confirm(`Hapus kategori ${c.name}?`)){await del('categories',id);await renderCategoryMaster();await renderProducts()}};

async function renderProducts(){let ps=await all('products');let masters=await all('categories');let cats=[...new Set([...masters.map(c=>c.name),...ps.map(p=>p.category||'Umum')])];$('categoryFilter').innerHTML='<option value="">Semua kategori</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');$('pCategory').innerHTML='<option value="">Pilih kategori</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');let q=($('productSearch')?.value||'').toLowerCase();let f=$('categoryFilter').value;ps=ps.filter(p=>(p.name+' '+(p.sku||'')).toLowerCase().includes(q)&&(!f||p.category===f));$('productTable').innerHTML=table(ps.map(p=>`<tr><td>${p.photo?`<img class="product-photo" src="${p.photo}">`:''}<b>${esc(p.name)}</b><small>${esc(p.sku||'')}</small></td><td>${esc(p.category||'Umum')}</td><td>${rupiah(p.costPrice||0)}</td><td>${rupiah(p.price)}</td><td>${p.stock==null?'—':p.stock}</td><td><button class="link" onclick="openProduct('${p.id}')">Edit</button> <button class="link" onclick="removeProduct('${p.id}')">Hapus</button></td></tr>`),['Produk','Kategori','HPP','Harga jual','Stok','Aksi']);}
$('productSearch').oninput=renderProducts;$('categoryFilter').onchange=renderProducts;
let pendingProductPhoto='';
async function openProduct(id){$('productForm').reset();$('editProductId').value='';pendingProductPhoto='';$('pPhotoPreview').style.display='none';$('productDialogTitle').textContent='Tambah produk';if(id){if(!await requirePin('Edit produk'))return;let p=(await all('products')).find(x=>x.id===id);if(!p)return;$('editProductId').value=p.id;$('pName').value=p.name;$('pSku').value=p.sku||'';$('pCategory').value=p.category||'';$('pPrice').value=p.price;$('pCost').value=p.costPrice??0;$('pStock').value=p.stock??'';pendingProductPhoto=p.photo||'';if(p.photo){$('pPhotoPreview').src=p.photo;$('pPhotoPreview').style.display='block'}$('productDialogTitle').textContent='Edit produk'}$('productDialog').showModal()}
$('pPhoto').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return toast('Pilih file gambar');if(f.size>5*1024*1024)return toast('Foto maksimal 5 MB');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,720/Math.max(im.width,im.height));c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);pendingProductPhoto=c.toDataURL('image/jpeg',.72);$('pPhotoPreview').src=pendingProductPhoto;$('pPhotoPreview').style.display='block'};im.src=data};
async function captureProductPhoto(source){try{const photo=await Camera.getPhoto({quality:72,width:900,height:900,allowEditing:true,resultType:CameraResultType.DataUrl,source});if(!photo.dataUrl)return;pendingProductPhoto=photo.dataUrl;$('pPhotoPreview').src=photo.dataUrl;$('pPhotoPreview').style.display='block'}catch(err){if(!String(err).toLowerCase().includes('cancel'))toast('Foto tidak dapat diambil: '+err.message)}}
$('takeProductPhoto').onclick=()=>captureProductPhoto(CameraSource.Camera);$('chooseProductPhoto').onclick=()=>captureProductPhoto(CameraSource.Photos);
$('saveProduct').onclick=async e=>{e.preventDefault();let id=$('editProductId').value||uid(),old=(await all('products')).find(x=>x.id===id)||{};await put('products',{...old,id,name:$('pName').value.trim(),sku:$('pSku').value.trim(),category:$('pCategory').value.trim()||'Umum',price:Number($('pPrice').value),costPrice:Number($('pCost').value)||0,stock:$('pStock').value===''?null:Number($('pStock').value),photo:pendingProductPhoto});$('productDialog').close();await renderProducts();await renderPOS();await renderDashboard();toast('Produk disimpan')};
async function removeProduct(id){if(!await requirePin('Hapus produk'))return;if(confirm('Hapus produk ini?')){await del('products',id);await renderProducts();await renderPOS();toast('Produk dihapus')}}
async function renderPOS(){let ps=await all('products'),q=($('posSearch')?.value||'').toLowerCase(),cat=$('posCategory').value;let cats=[...new Set(ps.map(p=>p.category))];$('posCategory').innerHTML='<option value="">Semua kategori</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');$('posProducts').innerHTML=ps.filter(p=>(p.name+' '+(p.sku||'')).toLowerCase().includes(q)&&(!cat||p.category===cat)).map(p=>`<button class="product-card" onclick="addCart('${p.id}')">${p.photo?`<img src="${p.photo}" alt="">`:''}<b>${esc(p.name)}</b><small>${esc(p.category||'Umum')}</small><span>${rupiah(p.price)}</span></button>`).join('')||'<div class="empty">Belum ada produk. Tambahkan produk dahulu.</div>';$('cashierName').textContent=$('cashier').value||'Pemilik';drawCart()}
$('posSearch').oninput=renderPOS;$('posCategory').onchange=renderPOS;
async function addCart(id){let p=(await all('products')).find(x=>x.id===id);if(!p)return;let line=cart.find(x=>x.productId===id);if(line)line.qty++;else cart.push({productId:p.id,name:p.name,price:p.price,costPrice:p.costPrice||0,sku:p.sku||'',qty:1,category:p.category});drawCart()}
function drawCart(){let c=$('cartItems');c.innerHTML=cart.length?cart.map(x=>`<div class="cart-row"><div><b>${esc(x.name)}</b><small>${rupiah(x.price)} × ${x.qty} = ${rupiah(x.price*x.qty)}</small></div><div class="qty"><button onclick="changeQty('${x.productId}',-1)">−</button><b>${x.qty}</b><button onclick="changeQty('${x.productId}',1)">＋</button></div></div>`).join(''):'<div class="empty">Belum ada produk dipilih.</div>';let sub=cart.reduce((a,x)=>a+x.price*x.qty,0),disc=Math.max(0,Number($('discount').value)||0),total=Math.max(0,sub-disc);$('subtotal').textContent=rupiah(sub);$('grandTotal').textContent=rupiah(total);$('change').textContent=rupiah(Math.max(0,(Number($('paid').value)||0)-total));$('cashFields').hidden=$('payment').value==='Tempo / Kasbon'}
function changeQty(id,n){let x=cart.find(x=>x.productId===id);if(!x)return;x.qty+=n;if(x.qty<=0)cart=cart.filter(y=>y!==x);drawCart()}
$('discount').oninput=drawCart;$('paid').oninput=drawCart;$('payment').onchange=drawCart;$('cashier').oninput=()=>{$('cashierName').textContent=$('cashier').value};
$('clearCart').onclick=()=>{cart=[];drawCart()};
$('completeSale').onclick=async()=>{if(!cart.length)return toast('Keranjang masih kosong');let sub=cart.reduce((a,x)=>a+x.price*x.qty,0),discount=Math.max(0,Number($('discount').value)||0);if(discount>sub)return toast('Diskon tidak boleh melebihi subtotal');let total=sub-discount,payment=$('payment').value,paid=payment==='Tempo / Kasbon'?0:Number($('paid').value)||0;if(payment!=='Tempo / Kasbon'&&paid<total)return toast('Uang diterima belum mencukupi');let tx={id:uid(),invoice:'INV-'+Date.now().toString().slice(-8),createdAt:Date.now(),date:today(),time:new Date().toLocaleTimeString('id-ID'),items:cart.map(x=>({...x})),subtotal:sub,discount,total,type:document.querySelector('[name=txType]:checked').value,payment,paid,change:Math.max(0,paid-total),customer:$('customer').value.trim(),note:$('orderNote').value.trim(),cashier:$('cashier').value.trim()||'Pemilik'};await put('transactions',tx);lastReceipt=tx;cart=[];$('discount').value=0;$('paid').value='';$('customer').value='';$('orderNote').value='';drawCart();await refreshAll();toast('Transaksi tersimpan: '+tx.invoice);showDetail(tx.id)};
async function renderHistory(){let tx=await all('transactions'),q=($('historySearch')?.value||'').toLowerCase(),d=$('historyDate').value,t=$('historyType').value;tx=tx.filter(x=>(!d||x.date===d)&&(!t||x.type===t)&&(x.invoice+' '+x.customer+' '+x.cashier).toLowerCase().includes(q)).sort((a,b)=>b.createdAt-a.createdAt);$('historyTable').innerHTML=table(tx.map(x=>`<tr><td><b>${x.invoice}</b></td><td>${x.date} ${x.time}</td><td>${esc(x.customer||'—')}</td><td>${x.type}</td><td>${x.payment}</td><td>${esc(x.cashier)}</td><td><b>${rupiah(x.total)}</b></td><td><button class="link" onclick="showDetail('${x.id}')">Detail</button></td></tr>`),['Nota','Tanggal','Pelanggan','Tipe','Pembayaran','Kasir','Total','']);}
['historySearch','historyDate','historyType'].forEach(id=>$(id).oninput=renderHistory);
async function showDetail(id){let tx=(await all('transactions')).find(x=>x.id===id);if(!tx)return;$('detailContent').innerHTML=`<h2>${esc(tx.invoice)}</h2><p class="muted">${tx.date} ${tx.time} · ${tx.type}</p><p>Pelanggan: ${esc(tx.customer||'—')}<br>Kasir: ${esc(tx.cashier)}<br>Metode: ${tx.payment}</p>${table(tx.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${rupiah(i.price*i.qty)}</td></tr>`),['Produk','Qty','Jumlah'])}<p>Subtotal: <b>${rupiah(tx.subtotal)}</b><br>Diskon: ${rupiah(tx.discount)}<br><strong>Total: ${rupiah(tx.total)}</strong><br>Dibayar: ${rupiah(tx.paid)} · Kembali: ${rupiah(tx.change)}</p><p>${esc(tx.note||'')}</p>`;$('printDetail').onclick=()=>printReceipt(tx);$('shareDetail').onclick=()=>shareReceipt(tx);$('editTransaction').onclick=()=>openTransactionEdit(tx);$('detailDialog').showModal()}
let expenseTab='list';
const EXP_GROUPS={bahan:'Belanja Bahan',operasional:'Belanja Operasional',gaji:'Gaji Karyawan'};
const EXP_METHODS=['Tunai','QRIS','Transfer Bank','E-Wallet'];
const defaultExpenseGroup=t=>t==='Bahan baku'?'bahan':t==='Gaji'?'gaji':'operasional';
function expenseRange(){let f=$('expFrom'),t=$('expTo');if(!f.value)f.value=today().slice(0,8)+'01';if(!t.value)t.value=today();return{from:f.value,to:t.value}}
const GROUP_BADGE={bahan:['Bahan','g-bahan'],operasional:['Operasional','g-oper'],gaji:['Gaji','g-gaji']};
const dmy=d=>{let p=String(d||'').split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:esc(d)};
async function renderExpenses(){
document.querySelectorAll('[data-exp-tab]').forEach(b=>b.classList.toggle('active',b.dataset.expTab===expenseTab));
for(const k of ['list','staff','report'])$('expPane-'+k).hidden=k!==expenseTab;
$('expFilters').hidden=expenseTab==='staff';
if(expenseTab==='staff'){await renderEmployees();return}
let {from,to}=expenseRange(),{groups}=await getExpenseMasters();
let es=(await all('expenses')).filter(x=>x.date>=from&&x.date<=to).sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||0)-(a.createdAt||0));
let grp=x=>groups[x.type]||defaultExpenseGroup(x.type),sum=l=>l.reduce((n,x)=>n+(Number(x.amount)||0),0);
if(expenseTab==='list'){
let total=sum(es),badge=x=>{let [t,c]=GROUP_BADGE[grp(x)];return `<span class="gbadge ${c}">${t}</span>`};
if(!es.length){$('expenseTable').innerHTML='<div class="empty-state"><b>Belum ada pengeluaran</b><span>Tidak ada catatan pada periode ini. Tekan “＋ Tambah pengeluaran” untuk mulai mencatat.</span></div>';return}
let tbl=table(es.map(e=>`<tr><td>${dmy(e.date)}</td><td>${esc(e.type||'Lainnya')}<br>${badge(e)}</td><td><b>${esc(e.name)}</b>${e.note?`<small>${esc(e.note)}</small>`:''}</td><td class="num">${esc(e.qty||1)} ${esc(e.unit||'')}</td><td class="num">${rupiah(e.unitPrice)}</td><td class="num"><b>${rupiah(e.amount)}</b></td><td>${esc(e.payment||'Tunai')}</td><td>${esc(e.employeeName||'—')}</td><td class="act"><button class="link" onclick="editExpense('${e.id}')">Edit</button><button class="link danger-link" onclick="deleteExpense('${e.id}')">Hapus</button></td></tr>`),['Tanggal','Jenis','Item','Qty','Harga satuan','Nominal','Metode bayar','Karyawan','Aksi']);
let cards=es.map(e=>`<article class="exp-card"><div class="exp-card-top"><div><b>${esc(e.name)}</b><small>${dmy(e.date)} · ${esc(e.type||'Lainnya')}</small></div><strong>${rupiah(e.amount)}</strong></div><div class="exp-card-meta">${badge(e)}<span>${esc(e.qty||1)} ${esc(e.unit||'')} × ${rupiah(e.unitPrice)}</span><span class="pay">${esc(e.payment||'Tunai')}</span>${e.employeeName?`<span>👤 ${esc(e.employeeName)}</span>`:''}</div>${e.note?`<p>${esc(e.note)}</p>`:''}<div class="exp-card-actions"><button class="outline" onclick="editExpense('${e.id}')">Edit</button><button class="outline danger" onclick="deleteExpense('${e.id}')">Hapus</button></div></article>`).join('');
$('expenseTable').innerHTML=`<div class="exp-desktop">${tbl}</div><div class="exp-cards">${cards}</div><div class="exp-total"><span>${es.length} catatan</span><b>Total ${rupiah(total)}</b></div>`;
return}
let bahan=sum(es.filter(x=>grp(x)==='bahan')),oper=sum(es.filter(x=>grp(x)==='operasional')),gaji=sum(es.filter(x=>grp(x)==='gaji')),total=sum(es);
$('expenseReportCards').innerHTML=`<article class="hero"><small>Total pengeluaran</small><strong>${rupiah(total)}</strong><span>${es.length} catatan · ${dmy(from)} – ${dmy(to)}</span></article>`+[['Belanja Bahan',bahan,'Bahan baku & belanja bahan','c-bahan'],['Belanja Operasional',oper,'Biaya operasional usaha','c-oper'],['HPP',bahan+oper,'Belanja Bahan + Belanja Operasional','c-hpp'],['Gaji Karyawan',gaji,'Pembayaran gaji','c-gaji']].map(([a,v,n,c])=>`<article class="${c}"><small>${a}</small><strong>${rupiah(v)}</strong><span>${n}</span></article>`).join('');
let byPay={};EXP_METHODS.forEach(m=>byPay[m]={n:0,v:0});es.forEach(x=>{let m=x.payment||'Tunai';byPay[m]??={n:0,v:0};byPay[m].n++;byPay[m].v+=Number(x.amount)||0});
$('expenseReportPay').innerHTML=Object.entries(byPay).sort((a,b)=>b[1].v-a[1].v).map(([m,o])=>{let pct=total?o.v/total*100:0;return `<div class="pay-row"><div class="pay-top"><b>${esc(m)}</b><span>${o.n} catatan</span><strong>${rupiah(o.v)}</strong></div><div class="pay-bar"><i style="width:${pct.toFixed(1)}%"></i></div><small>${pct.toFixed(1)}% dari total</small></div>`}).join('')}
document.querySelectorAll('[data-exp-tab]').forEach(b=>b.onclick=()=>{expenseTab=b.dataset.expTab;renderExpenses()});
['expFrom','expTo'].forEach(id=>$(id).addEventListener('change',renderExpenses));
$('expThisMonth').onclick=()=>{$('expFrom').value=today().slice(0,8)+'01';$('expTo').value=today();renderExpenses()};
async function getExpenseMasters(){let s=(await all('settings')).find(x=>x.id==='main')||{};let types=s.expenseTypes||['Bahan baku','Operasional','Utilitas','Transportasi','Gaji','Lainnya'];let items=s.expenseItems||{'Operasional':['Biaya operasional'],'Bahan baku':['Bahan makanan'],'Gaji':['Gaji karyawan'],'Utilitas':['Listrik','Air','Gas'],'Transportasi':['Transportasi'],'Lainnya':['Lainnya']};let groups={};types.forEach(t=>groups[t]=(s.expenseGroups||{})[t]||defaultExpenseGroup(t));return {s,types,items,groups}}
async function saveExpenseMasters(types,items,s){await put('settings',{...s,id:'main',expenseTypes:types,expenseItems:items})}
async function refreshExpenseItemOptions(){let {types,items}=await getExpenseMasters(),t=$('eType').value;$('eName').innerHTML=(items[t]||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'<option value="__custom__">+ Item lain (ketik)</option>';}
