async function renderExpenseMasters(){let {types,items,groups}=await getExpenseMasters();{let cur=$('expenseMasterSelect').value;$('expenseMasterSelect').innerHTML=types.map(x=>`<option>${esc(x)}</option>`).join('');if(types.includes(cur))$('expenseMasterSelect').value=cur}$('expenseMasterList').innerHTML=types.map(t=>`<div class="master-expense-row"><div class="mrow-head"><b>${esc(t)}</b><select class="group-select" onchange="setExpenseTypeGroup('${encodeURIComponent(t)}',this.value)" aria-label="Kelompok jenis ${esc(t)}">${Object.entries(EXP_GROUPS).map(([k,v])=>`<option value="${k}"${groups[t]===k?' selected':''}>${v}</option>`).join('')}</select><button type="button" class="link" onclick="editExpenseType('${encodeURIComponent(t)}')">Edit</button><button type="button" class="link danger-link" onclick="deleteExpenseType('${encodeURIComponent(t)}')">Hapus</button></div><div class="mitems">${(items[t]||[]).map(i=>`<span class="chip">${esc(i)} <button type="button" class="link" onclick="editExpenseMasterItem('${encodeURIComponent(t)}','${encodeURIComponent(i)}')">Edit</button> <button type="button" class="link danger-link" onclick="deleteExpenseMasterItem('${encodeURIComponent(t)}','${encodeURIComponent(i)}')">Hapus</button></span>`).join('')||'<small>Belum ada item</small>'}</div></div>`).join('')}
window.setExpenseTypeGroup=async(encoded,val)=>{let t=decodeURIComponent(encoded);if(!await requirePin('mengubah kelompok jenis pengeluaran')){renderExpenseMasters();return}let {s,types,items}=await getExpenseMasters();await saveExpenseMasters(types,items,{...s,expenseGroups:{...(s.expenseGroups||{}),[t]:val}});await renderExpenseMasters();renderExpenses();toast('Kelompok jenis diperbarui')};
