function dateRange(){let p=$('period').value,now=new Date(),from,to;if(p==='custom'){from=$('fromDate').value||'0000-01-01';to=$('toDate').value||today()}else if(p==='day'){from=to=today()}else if(p==='week'){let d=new Date(now);d.setDate(d.getDate()-((d.getDay()+6)%7));from=d.toISOString().slice(0,10);to=today()}else if(p==='month'){from=today().slice(0,7)+'-01';to=today()}else{from=today().slice(0,4)+'-01-01';to=today()}$('fromDate').value=from;$('toDate').value=to;return{from,to}}
async function renderReports(){if(!$('fromDate').value)dateRange();let {from,to}=dateRange(),tx=await all('transactions');reportRows=tx.filter(x=>x.date>=from&&x.date<=to&&(!$('reportType').value||x.type===$('reportType').value)&&(!$('reportPayment').value||x.payment===$('reportPayment').value)).sort((a,b)=>a.createdAt-b.createdAt);let sum=reportRows.reduce((a,x)=>a+x.total,0),disc=reportRows.reduce((a,x)=>a+x.discount,0),cogs=reportRows.reduce((a,x)=>a+x.items.reduce((b,i)=>b+(Number(i.costPrice)||0)*(Number(i.qty)||0),0),0),expenses=(await all('expenses')).filter(x=>x.date>=from&&x.date<=to).reduce((a,x)=>a+(Number(x.amount)||0),0),profit=sum-cogs-expenses;$('rSales').textContent=rupiah(sum);$('rCount').textContent=reportRows.length;$('rAverage').textContent=rupiah(reportRows.length?sum/reportRows.length:0);$('rProfit').textContent=rupiah(profit);renderReportTab();$('reportDetail').innerHTML=table(reportRows.map(x=>`<tr><td>${x.invoice}</td><td>${x.date} ${x.time}</td><td>${esc(x.customer||'—')}</td><td>${x.type}</td><td>${x.payment}</td><td>${esc(x.cashier)}</td><td>${x.items.map(i=>esc(i.name)+' × '+i.qty).join('; ')}</td><td>${rupiah(x.subtotal)}</td><td>${rupiah(x.discount)}</td><td><b>${rupiah(x.total)}</b></td></tr>`),['Nota','Tanggal','Pelanggan','Tipe transaksi','Metode pembayaran','Kasir','Rincian item','Subtotal','Diskon','Total'])}
function renderReportTab(){let rows=reportRows;if(['cashbook','cashflow'].includes(activeReport)){renderFinancialFlow(activeReport);return}if(activeReport==='profitloss'){renderProfitLoss();return}if(activeReport==='depreciation'){renderDepreciationReport();return}if(activeReport==='summary'){$('reportResult').innerHTML=table(rows.map(x=>`<tr><td>${x.date}</td><td>${x.invoice}</td><td>${x.type}</td><td>${x.payment}</td><td>${esc(x.cashier)}</td><td>${rupiah(x.total)}</td></tr>`),['Tanggal','Nota','Tipe','Pembayaran','Kasir','Total']);return}let map={};rows.forEach(x=>{let add=(k,v)=>{map[k]??={name:k,count:0,total:0,qty:0};map[k].count++;map[k].total+=v};if(activeReport==='type')add(x.type,x.total);if(activeReport==='payment')add(x.payment,x.total);if(activeReport==='cashier')add(x.cashier||x.employeeName||'Tidak diketahui',x.total);if(activeReport==='product')x.items.forEach(i=>{map[i.name]??={name:i.name,count:0,total:0,qty:0};map[i.name].count++;map[i.name].total+=i.price*i.qty;map[i.name].qty+=i.qty});if(activeReport==='category')x.items.forEach(i=>{let k=i.category||'Umum';map[k]??={name:k,count:0,total:0,qty:0};map[k].count++;map[k].total+=i.price*i.qty;map[k].qty+=i.qty})});let vals=Object.values(map).sort((a,b)=>b.total-a.total);$('reportResult').innerHTML=table(vals.map(v=>`<tr><td><b>${esc(v.name)}</b></td><td>${v.count}</td><td>${v.qty||'—'}</td><td>${rupiah(v.total)}</td></tr>`),['Nama / Kelompok','Jumlah baris','Qty terjual','Total penjualan'])}
