$('period').onchange=()=>{dateRange();renderReports()};$('applyReport').onclick=renderReports;$('reportType').onchange=renderReports;$('reportPayment').onchange=renderReports;
function crc32(bytes){let c=~0;for(let b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (~c)>>>0}
function u16(n){return [n&255,(n>>>8)&255]} function u32(n){return [n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}
function zipStore(entries){let local=[],central=[],offset=0;const enc=new TextEncoder();for(const [name,content] of entries){let nb=enc.encode(name),data=enc.encode(content),crc=crc32(data);let lh=[0x50,0x4b,3,4,...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(nb.length),...u16(0),...nb,...data];local.push(new Uint8Array(lh));let ch=[0x50,0x4b,1,2,...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(nb.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...nb];central.push(new Uint8Array(ch));offset+=lh.length}let csize=central.reduce((a,x)=>a+x.length,0),count=entries.length;let end=new Uint8Array([0x50,0x4b,5,6,...u16(0),...u16(0),...u16(count),...u16(count),...u32(csize),...u32(offset),...u16(0)]);return new Blob([...local,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function colName(n){let s='';while(n){let r=(n-1)%26;s=String.fromCharCode(65+r)+s;n=Math.floor((n-1)/26)}return s}
function makeSheet(rows){let escx=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');let body=rows.map((r,ri)=>'<row r="'+(ri+1)+'">'+r.map((v,ci)=>{let ref=colName(ci+1)+(ri+1);return typeof v==='number'&&Number.isFinite(v)?'<c r="'+ref+'"><v>'+v+'</v></c>':'<c r="'+ref+'" t="inlineStr"><is><t>'+escx(v)+'</t></is></c>'}).join('')+'</row>').join('');return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+body+'</sheetData></worksheet>'}
$('exportReport').onclick=()=>{let rows=[['Nomor Nota','Tanggal','Waktu','Pelanggan','Tipe Transaksi','Metode Pembayaran','Kasir','Nama Produk','SKU','Kategori','Qty','HPP Satuan','Harga Jual Satuan','Total HPP Item','Subtotal Item','Subtotal Transaksi','Diskon Transaksi','Total Transaksi','Uang Diterima','Kembalian','Catatan','Laba Kotor Item']];reportRows.forEach(x=>x.items.forEach(i=>{let c=Number(i.costPrice)||0;rows.push([x.invoice,x.date,x.time,x.customer,x.type,x.payment,x.cashier,i.name,i.sku||'',i.category,i.qty,c,i.price,c*i.qty,i.qty*i.price,x.subtotal,x.discount,x.total,x.paid,x.change,x.note,(i.price-c)*i.qty])}));let ct='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>',rels='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',wb='<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Rincian Penjualan" sheetId="1" r:id="rId1"/></sheets></workbook>',wr='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>';let blob=zipStore([['[Content_Types].xml',ct],['_rels/.rels',rels],['xl/workbook.xml',wb],['xl/_rels/workbook.xml.rels',wr],['xl/worksheets/sheet1.xml',makeSheet(rows)]]);download(blob,'laporan-penjualan-'+today()+'.xlsx');toast('File Excel .xlsx berhasil diekspor')};
async function download(blob,name){if(isNative){try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)});const saved=await Filesystem.writeFile({path:name,data,directory:Directory.Cache});await Share.share({title:'Simpan '+name,text:'File Kasmini POS',url:saved.uri,dialogTitle:'Bagikan atau simpan file'});return}catch(err){console.error(err);toast('Gagal menyiapkan file: '+err.message);return}}let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function xmlEsc(v){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
