$('backupData').onclick=async()=>{let data={version:2,exportedAt:new Date().toISOString(),products:await all('products'),transactions:await all('transactions'),expenses:await all('expenses'),customers:await all('customers'),employees:await all('employees'),salaryPayments:await all('salaryPayments'),categories:await all('categories'),stockMovements:await all('stockMovements'),assets:await all('assets'),liabilities:await all('liabilities'),receivables:await all('receivables'),openingBalance:await all('openingBalance'),tables:await all('tables'),orders:await all('orders'),settings:await all('settings')};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'backup-pos-'+today()+'.json')};
