async function printReceipt(tx){let settings=(await all('settings'))[0]||{};let logo=settings.logo?`<img src="${settings.logo}" style="max-width:150px;max-height:70px;object-fit:contain">`:'';let w=window.open('','_blank','width=380,height=650');if(!w)return toast('Izinkan pop-up untuk mencetak');w.document.write(`<html><body style="font:12px monospace;width:280px"><center>${logo}<h3>${esc($('storeName').value)}</h3>${esc($('storeAddress').value)}<hr><b>${tx.invoice}</b><br>${tx.date} ${tx.time}<br>${tx.type}</center><hr>${tx.items.map(i=>`${esc(i.name)}<br>${i.qty} x ${rupiah(i.price)} = ${rupiah(i.qty*i.price)}<br>`).join('')}<hr>Subtotal: ${rupiah(tx.subtotal)}<br>Diskon: ${rupiah(tx.discount)}<br><b>Total: ${rupiah(tx.total)}</b><br>Bayar: ${rupiah(tx.paid)}<br>Kembali: ${rupiah(tx.change)}<br>Metode: ${tx.payment}<hr><center>${esc($('receiptFooter').value)}</center><script>window.print()<\/script></body></html>`);w.document.close()}
