// Android hardware/system back button: return to dashboard first, then ask before exit.
const exitDialog = $('exitDialog');
$('cancelExit').onclick = () => exitDialog.close();
$('confirmExit').onclick = async () => {
  exitDialog.close();
  if (isNative) await App.exitApp();
};
if (isNative) {
  App.addListener('backButton', ({ canGoBack }) => {
    const openDialog = document.querySelector('dialog[open]');
    if (openDialog) { openDialog.close(); return; }
    const current = document.querySelector('.page.active')?.id || 'dashboard';
    if (current !== 'dashboard') { showPage('dashboard'); return; }
    if (!exitDialog.open) exitDialog.showModal();
  }).catch(err => console.warn('Listener tombol kembali tidak tersedia:', err));
}

