const bytesToHex=b=>Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('');
async function hashPin(pin,salt){const data=new TextEncoder().encode(`${salt}:${pin}`);return bytesToHex(await crypto.subtle.digest('SHA-256',data))}
async function requirePin(reason='Aksi admin'){const s=(await all('settings'))[0]||{};const dlg=$('pinDialog');$('pinEntry').value='';$('pinConfirm').value='';$('pinTitle').textContent=s.pinHash?'Verifikasi PIN':'Buat PIN keamanan';$('pinMessage').textContent=s.pinHash?`Masukkan PIN 6 digit untuk ${reason}.`:'Buat PIN keamanan 6 digit untuk melindungi menu admin.';$('pinEntryLabel').querySelector('span');$('pinConfirmLabel').hidden=!!s.pinHash;$('pinCancel').hidden=false;dlg.dataset.reason=reason;dlg.showModal();return new Promise(resolve=>{dlg._resolve=resolve;$('pinEntry').focus()})}
$('pinCancel').onclick=()=>{$('pinDialog').close();$('pinDialog')._resolve?.(false)};
$('pinForm').onsubmit=async e=>{e.preventDefault();let pin=$('pinEntry').value,s=(await all('settings'))[0]||{};if(!/^\d{6}$/.test(pin)){toast('PIN harus tepat 6 angka');return}if(!s.pinHash){if(pin!==$('pinConfirm').value){toast('Konfirmasi PIN tidak sama');return}let salt=bytesToHex(crypto.getRandomValues(new Uint8Array(16)));await put('settings',{...s,id:'main',pinSalt:salt,pinHash:await hashPin(pin,salt)});$('pinDialog').close();$('pinDialog')._resolve?.(true);toast('PIN keamanan berhasil dibuat');return}if(await hashPin(pin,s.pinSalt)===s.pinHash){$('pinDialog').close();$('pinDialog')._resolve?.(true);return}toast('PIN salah');$('pinEntry').value='';$('pinEntry').focus()};
async function requestProtectedPage(id){const ok=await requirePin(id==='reports'?'membuka laporan':'membuka pengaturan');if(ok){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id));if(id==='reports')await renderReports()}}
$('changePin').onclick=async()=>{let s=(await all('settings'))[0]||{};if(s.pinHash&&!await requirePin('mengganti PIN'))return;let pin=prompt('Masukkan PIN baru 6 angka:');if(!pin)return;if(!/^\d{6}$/.test(pin))return toast('PIN harus tepat 6 angka');let confirmPin=prompt('Ulangi PIN baru:');if(pin!==confirmPin)return toast('Konfirmasi PIN tidak sama');let salt=bytesToHex(crypto.getRandomValues(new Uint8Array(16)));await put('settings',{...s,id:'main',pinSalt:salt,pinHash:await hashPin(pin,salt)});toast('PIN berhasil diperbarui')};

// ---- Customer management and CSV upsert ----
function csvParse(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field);rows.push(row);row=[];field=''}else if(c!=='\r')field+=c}row.push(field);if(row.some(x=>x!==''))rows.push(row);return rows}
function csvCell(v){let s=String(v??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function downloadText(text,name,type='text/csv;charset=utf-8'){let blob=new Blob(['\ufeff'+text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
async function renderCustomers(){let xs=await all('customers'),q=($('customerSearch')?.value||'').toLowerCase();xs=xs.filter(x=>(x.name+' '+x.phone+' '+x.code).toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));$('customerTable').innerHTML=table(xs.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.code||'')}</small></td><td>${esc(x.phone||'—')}</td><td>${esc(x.address||'—')}</td><td><button class="link" onclick="editCustomer('${x.id}')">Edit</button> <button class="link" onclick="deleteCustomer('${x.id}')">Hapus</button></td></tr>`),['Pelanggan','Nomor HP','Alamat','Aksi'])}
// Native Android contacts: safe upsert by normalized phone; preserve existing customer details.
function normalizePhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('0'))digits='62'+digits.slice(1);if(digits.startsWith('8'))digits='62'+digits;return digits}
$('syncPhoneContacts').onclick=async()=>{
  if(!isNative)return toast('Sinkronisasi kontak HP hanya tersedia pada aplikasi Android');
  const button=$('syncPhoneContacts');button.disabled=true;button.textContent='Membaca kontak…';
  try{
    const result=await PhoneContacts.getContacts();
    const contacts=Array.isArray(result?.contacts)?result.contacts:[];
    const current=await all('customers');let added=0,updated=0,skipped=0;
    const byPhone=new Map(current.filter(x=>x.phone).map(x=>[normalizePhone(x.phone),x]));
    for(const contact of contacts){
      const name=String(contact?.name||'').trim(),phone=String(contact?.phone||'').trim();
      if(!name||!phone){skipped++;continue}const key=normalizePhone(phone);if(!key){skipped++;continue}
      const old=byPhone.get(key);
      const obj={...(old||{}),id:old?.id||uid(),code:old?.code||'',name:old?.name||name,phone:old?.phone||phone,address:old?.address||'',email:old?.email||'',note:old?.note||'',phoneContactId:String(contact.contactId||'')};
      await put('customers',obj);if(old)updated++;else{added++;byPhone.set(key,obj)}
    }
    await renderCustomers();toast(`Kontak selesai: ${added} baru, ${updated} cocok, ${skipped} dilewati`);
  }catch(err){console.error('Sinkronisasi kontak gagal',err);toast('Sinkronisasi kontak gagal: '+(err?.message||err))}
  finally{button.disabled=false;button.textContent='↻ Sinkronkan Kontak HP'}
};

$('customerSearch').oninput=renderCustomers;$('addCustomer').onclick=()=>openCustomer();$('importCustomers').onclick=()=>$('customerCsv').click();$('customerTemplate').onclick=()=>downloadText('kode_pelanggan,nama,no_hp,alamat,email,keterangan\nDBL001,Contoh Pelanggan,081234567890,Alamat contoh,,Catatan\n','template-pelanggan-dbl.csv');
$('exportCustomers').onclick=async()=>{let xs=await all('customers'),head=['kode_pelanggan','nama','no_hp','alamat','email','keterangan'];downloadText([head.join(','),...xs.map(x=>[x.code,x.name,x.phone,x.address,x.email,x.note].map(csvCell).join(','))].join('\r\n'),'data-pelanggan-'+today()+'.csv')};
$('customerCsv').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;try{let rows=csvParse(await f.text());if(rows.length<2)throw Error('CSV tidak berisi baris data');let heads=rows.shift().map(x=>x.trim().toLowerCase().replace(/^\ufeff/,''));let idx=k=>heads.indexOf(k),get=(r,k)=>idx(k)>=0?(r[idx(k)]||'').trim():'';let current=await all('customers'),added=0,updated=0,errors=[];for(let n=0;n<rows.length;n++){let r=rows[n];if(!r.some(x=>x.trim()))continue;let name=get(r,'nama'),code=get(r,'kode_pelanggan'),phone=get(r,'no_hp').replace(/[\s-]/g,'');if(!name){errors.push(`Baris ${n+2}: nama kosong`);continue}let old=(code&&current.find(x=>x.code===code))||(phone&&current.find(x=>String(x.phone||'').replace(/[\s-]/g,'')===phone));let obj={...(old||{}),id:old?.id||uid(),code:code||old?.code||'',name,phone,address:get(r,'alamat'),email:get(r,'email'),note:get(r,'keterangan')};await put('customers',obj);if(old){updated++;current=current.map(x=>x.id===old.id?obj:x)}else{added++;current.push(obj)}}await renderCustomers();toast(`CSV selesai: ${added} baru, ${updated} diperbarui, ${errors.length} gagal`);if(errors.length)alert(errors.slice(0,20).join('\n'))}catch(err){toast('Import CSV gagal: '+err.message)}e.target.value=''};
async function openCustomer(id){if(id&&!await requirePin('mengubah pelanggan'))return;$('customerForm').reset();$('customerId').value=id||'';$('customerDialogTitle').textContent=id?'Edit pelanggan':'Tambah pelanggan';if(id)all('customers').then(xs=>{let x=xs.find(v=>v.id===id);if(!x)return;$('cCode').value=x.code||'';$('cName').value=x.name;$('cPhone').value=x.phone||'';$('cAddress').value=x.address||'';$('cEmail').value=x.email||'';$('cNote').value=x.note||'';$('customerDialog').showModal()});else $('customerDialog').showModal()}
window.editCustomer=id=>openCustomer(id);window.deleteCustomer=async id=>{if(!await requirePin('menghapus pelanggan'))return;if(confirm('Hapus pelanggan?')){await del('customers',id);renderCustomers()}};
$('saveCustomer').onclick=async e=>{e.preventDefault();let id=$('customerId').value||uid();await put('customers',{id,code:$('cCode').value.trim(),name:$('cName').value.trim(),phone:$('cPhone').value.trim(),address:$('cAddress').value.trim(),email:$('cEmail').value.trim(),note:$('cNote').value.trim()});$('customerDialog').close();renderCustomers();toast('Pelanggan disimpan')};

// ---- Employee master and payroll ----
async function renderEmployees(){let es=(await all('employees')).sort((a,b)=>String(a.name).localeCompare(String(b.name)));if(!es.length){$('employeeTable').innerHTML='<div class="empty-state"><b>Belum ada karyawan</b><span>Tekan “＋ Tambah karyawan” untuk menambahkan data karyawan.</span></div>';return}let tbl=table(es.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.position||'—')}</td><td>${dmy(x.startDate)}</td><td>${esc(x.phone||'—')}</td><td>${esc(x.account||'—')}</td><td class="act"><button class="link" onclick="editEmployee('${x.id}')">Edit</button><button class="link danger-link" onclick="deleteEmployee('${x.id}')">Hapus</button></td></tr>`),['Nama','Posisi','Tanggal masuk','No. HP','No. rekening / e-wallet','Aksi']);let cards=es.map(x=>`<article class="exp-card"><div class="exp-card-top"><div><b>${esc(x.name)}</b><small>${esc(x.position||'—')} · masuk ${dmy(x.startDate)}</small></div></div><div class="emp-meta"><span>📞 ${esc(x.phone||'—')}</span><span>💳 ${esc(x.account||'—')}</span></div><div class="exp-card-actions"><button class="outline" onclick="editEmployee('${x.id}')">Edit</button><button class="outline danger" onclick="deleteEmployee('${x.id}')">Hapus</button></div></article>`).join('');$('employeeTable').innerHTML=`<div class="exp-desktop">${tbl}</div><div class="exp-cards">${cards}</div>`}
$('addEmployee').onclick=()=>openEmployee();
async function openEmployee(id){if(id&&!await requirePin('mengubah karyawan'))return;$('employeeForm').reset();$('employeeId').value=id||'';$('employeeDialogTitle').textContent=id?'Edit karyawan':'Tambah karyawan';if(id)all('employees').then(xs=>{let x=xs.find(y=>y.id===id);if(!x)return;$('employeeName').value=x.name;$('employeeStart').value=x.startDate||'';$('employeePosition').value=x.position||'';$('employeePhone').value=x.phone||'';$('employeeAccount').value=x.account||'';$('employeeDialog').showModal()});else $('employeeDialog').showModal()}
window.editEmployee=id=>openEmployee(id);window.deleteEmployee=async id=>{if(!await requirePin('menghapus karyawan'))return;if(confirm('Hapus data karyawan?')){await del('employees',id);renderEmployees()}};
$('saveEmployee').onclick=async e=>{e.preventDefault();let id=$('employeeId').value||uid();await put('employees',{id,name:$('employeeName').value.trim(),startDate:$('employeeStart').value,position:$('employeePosition').value.trim(),phone:$('employeePhone').value.trim(),account:$('employeeAccount').value.trim()});{let nm=$('employeeName').value.trim();for(let x of await all('expenses'))if(x.employeeId===id&&x.employeeName!==nm)await put('expenses',{...x,employeeName:nm})}$('employeeDialog').close();await renderEmployees();renderExpenses();toast('Data karyawan disimpan')};

// ---- Transaction editing (PIN protected) ----
async function openTransactionEdit(tx){if(!await requirePin('mengedit transaksi'))return;$('editTxId').value=tx.id;$('editTxCustomer').value=tx.customer||'';$('editTxDiscount').value=tx.discount||0;$('editTxPayment').value=tx.payment;$('editTxPaid').value=tx.paid||0;$('editTxNote').value=tx.note||'';$('detailDialog').close();$('editTxDialog').showModal()}
$('saveTxEdit').onclick=async e=>{e.preventDefault();let id=$('editTxId').value,tx=(await all('transactions')).find(x=>x.id===id);if(!tx)return;let discount=Math.max(0,Number($('editTxDiscount').value)||0);if(discount>tx.subtotal)return toast('Diskon melebihi subtotal');let total=tx.subtotal-discount,payment=$('editTxPayment').value,paid=payment==='Tempo / Kasbon'?0:Math.max(0,Number($('editTxPaid').value)||0);if(payment!=='Tempo / Kasbon'&&paid<total)return toast('Uang diterima kurang dari total');await put('transactions',{...tx,customer:$('editTxCustomer').value.trim(),discount,total,payment,paid,change:Math.max(0,paid-total),note:$('editTxNote').value.trim(),updatedAt:Date.now()});$('editTxDialog').close();await refreshAll();toast('Transaksi diperbarui');showDetail(id)};

// ---- WhatsApp/shareable receipt PDF ----
async function shareReceipt(tx){try{const s=(await all('settings'))[0]||{};const doc=new jsPDF({unit:'mm',format:[80,Math.max(120,80+tx.items.length*12)]});let y=10;if(s.logo){try{doc.addImage(s.logo,'PNG',25,y,30,16,undefined,'FAST');y+=19}catch(err){console.warn('Logo tidak dapat dimasukkan ke PDF:',err)}}doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text(s.name||'Kasir DBL',40,y,{align:'center'});y+=6;doc.setFont('helvetica','normal');doc.setFontSize(8);if(s.address){doc.text(String(s.address).slice(0,60),40,y,{align:'center'});y+=5}doc.text(`${tx.invoice} | ${tx.date} ${tx.time}`,4,y);y+=7;doc.line(4,y,76,y);y+=5;for(const i of tx.items){doc.text(String(i.name).slice(0,32),4,y);y+=4;doc.text(`${i.qty} x ${rupiah(i.price)} = ${rupiah(i.qty*i.price)}`,4,y);y+=5}doc.line(4,y,76,y);y+=6;for(const [k,v] of [['Subtotal',tx.subtotal],['Diskon',tx.discount],['TOTAL',tx.total],['Bayar',tx.paid],['Kembali',tx.change]]){doc.text(k,4,y);doc.text(rupiah(v),76,y,{align:'right'});y+=5}y+=4;doc.text(String(s.footer||'Terima kasih'),40,y,{align:'center'});const blob=doc.output('blob'),base64=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)});let fileName=`struk-${tx.invoice}.pdf`;if(isNative){let saved=await Filesystem.writeFile({path:fileName,data:base64,directory:Directory.Cache});await Share.share({title:`Struk ${tx.invoice}`,text:`Struk transaksi ${tx.invoice}`,url:saved.uri,dialogTitle:'Bagikan struk — pilih WhatsApp'});}else{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('PDF struk diunduh; lampirkan melalui WhatsApp')}}catch(err){toast('Gagal membagikan struk: '+err.message)}}

// ---- Bluetooth Classic SPP ESC/POS for paired RPP02N ----
let printerConnected=false;
async function refreshPrinters(){try{let r=await BluetoothSerial.listPairedDevices(),devices=r.devices||[];$('printerSelect').innerHTML='<option value="">Pilih printer</option>'+devices.map(d=>`<option value="${esc(d.address)}">${esc(d.name||'Bluetooth')} — ${esc(d.address)}</option>`).join('');let match=devices.find(d=>/RPP02N/i.test(d.name||''));if(match)$('printerSelect').value=match.address;$('printerStatus').textContent=devices.length?`${devices.length} perangkat dipasangkan`:'Tidak ada perangkat dipasangkan';}catch(err){$('printerStatus').textContent='Bluetooth tidak tersedia: '+err.message;toast('Pastikan Bluetooth aktif dan printer dipasangkan di Android')}}
$('refreshPrinters').onclick=refreshPrinters;
$('connectPrinter').onclick=async()=>{let address=$('printerSelect').value;if(!address)return toast('Pilih printer terlebih dahulu');try{await BluetoothSerial.connect({address});printerConnected=true;$('printerStatus').textContent='Terhubung ke '+$('printerSelect').selectedOptions[0].text;toast('Printer terhubung')}catch(err){printerConnected=false;toast('Gagal menghubungkan printer: '+err.message)}};
async function escposBytes(tx){let enc=new TextEncoder(),chunks=[],add=s=>chunks.push(...enc.encode(s)),cmd=a=>chunks.push(...a);cmd([0x1b,0x40]);let settings=(await all('settings'))[0]||{};if(settings.logo){try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=settings.logo});const scale=Math.min(1,384/img.width,160/img.height),width=Math.max(8,Math.round(img.width*scale)),height=Math.max(1,Math.round(img.height*scale)),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.drawImage(img,0,0,width,height);const px=ctx.getImageData(0,0,width,height).data,rowBytes=Math.ceil(width/8);cmd([0x1b,0x61,0x01,0x1d,0x76,0x30,0x00,rowBytes&255,(rowBytes>>8)&255,height&255,(height>>8)&255]);for(let y=0;y<height;y++)for(let bx=0;bx<rowBytes;bx++){let byte=0;for(let bit=0;bit<8;bit++){let x=bx*8+bit;if(x<width){let n=(y*width+x)*4,gray=(px[n]*299+px[n+1]*587+px[n+2]*114)/1000;if(gray<160)byte|=(0x80>>bit)}}chunks.push(byte)}cmd([0x1b,0x61,0x01])}catch(err){console.warn('Logo Bluetooth tidak dapat dirender:',err)}}cmd([0x1b,0x61,0x01]);let s=$('storeName').value||'Kasir DBL';add(s+'\n');add(($('storeAddress').value||'')+'\n');cmd([0x1b,0x61,0x00]);add('--------------------------------\n');add(`${tx.invoice}\n${tx.date} ${tx.time}\n${tx.type}\n`);add('--------------------------------\n');for(let i of tx.items){add(String(i.name).slice(0,32)+'\n');add(`${i.qty} x ${rupiah(i.price)} = ${rupiah(i.price*i.qty)}\n`)}add('--------------------------------\n');add(`Subtotal : ${rupiah(tx.subtotal)}\nDiskon   : ${rupiah(tx.discount)}\nTOTAL    : ${rupiah(tx.total)}\nBayar    : ${rupiah(tx.paid)}\nKembali  : ${rupiah(tx.change)}\n`);add(`Metode   : ${tx.payment}\nPelanggan: ${tx.customer||'-'}\n`);cmd([0x1b,0x61,0x01]);add(($('receiptFooter').value||'Terima kasih')+'\n\n\n');cmd([0x1d,0x56,0x41,0x03]);return btoa(String.fromCharCode(...chunks))}
async function printReceiptBluetooth(tx){if(!printerConnected)throw Error('Hubungkan printer Bluetooth terlebih dahulu');await BluetoothSerial.print({data:await escposBytes(tx)})}
const originalPrintReceipt=printReceipt;printReceipt=async tx=>{if(printerConnected){try{await printReceiptBluetooth(tx);toast('Struk dikirim ke printer RPP02N')}catch(e){toast('Cetak Bluetooth gagal: '+e.message)}}else originalPrintReceipt(tx)};
$('printLast').onclick=()=>lastReceipt?printReceipt(lastReceipt):toast('Belum ada transaksi pada sesi ini');

