// ---- KASIR 2.0: inventory movements, assets and debt/receivable records ----
async function editExpense(id){if(!await requirePin('mengubah pengeluaran'))return;openExpense(id)}
function stockKindLabel(k){return ({add:'Tambah',revision:'Revisi',waste:'Terbuang',usage:'Penggunaan'})[k]||k}
async function renderStock(){if(!$('stockTable'))return;let xs=(await all('stockMovements')).sort((a,b)=>(b.date||'').localeCompare(a.date||''));let filter=$('stockFilter')?.value||'all';if(filter!=='all')xs=xs.filter(x=>x.kind===filter);$('stockTable').innerHTML=table(xs.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.productName)}</td><td>${esc(stockKindLabel(x.kind))}</td><td>${Number(x.qty||0)}</td><td>${esc(x.note||'')}</td><td><button class="link" onclick="deleteStockMovement('${x.id}')">Hapus</button></td></tr>`),['Tanggal','Produk','Mutasi','Qty','Keterangan','Aksi'])}
async function openStock(kind){if(!await requirePin('mencatat mutasi stok'))return;let ps=await all('products');$('stockProduct').innerHTML=ps.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('stockForm').reset();$('stockDate').value=today();$('stockKind').value=kind;$('stockTitle').textContent=stockKindLabel(kind)+' stok';$('stockDialog').showModal()}
$('stockAdd')?.addEventListener('click',()=>openStock('add'));$('stockRevise')?.addEventListener('click',()=>openStock('revision'));$('stockWaste')?.addEventListener('click',()=>openStock('waste'));$('stockFilter')?.addEventListener('change',renderStock);
$('stockSave')?.addEventListener('click',async e=>{e.preventDefault();let p=(await all('products')).find(x=>x.id===$('stockProduct').value);if(!p)return toast('Pilih produk');let qty=Number($('stockQty').value)||0;if(qty<=0)return toast('Qty harus lebih dari nol');let kind=$('stockKind').value;let current=Number(p.stock||0),delta=kind==='add'?qty:kind==='waste'||kind==='usage'?-qty:kind==='revision'?qty-current:0;if(kind==='revision'&&!confirm(`Stok saat ini ${current}. Stok baru akan menjadi ${qty} (selisih ${delta}). Lanjutkan?`))return;await put('stockMovements',{id:uid(),productId:p.id,productName:p.name,kind,qty,delta,before:current,after:kind==='revision'?qty:Math.max(0,current+delta),date:$('stockDate').value,note:$('stockNote').value.trim(),createdAt:Date.now()});if(p.stock!==null&&p.stock!==undefined)await put('products',{...p,stock:kind==='revision'?qty:Math.max(0,current+delta)});$('stockDialog').close();await renderStock();await renderProducts();await renderDashboard();toast('Mutasi stok disimpan')});
window.deleteStockMovement=async id=>{if(!await requirePin('menghapus mutasi stok'))return;if(confirm('Hapus catatan mutasi ini? Catatan tidak akan mengembalikan stok secara otomatis.')){await del('stockMovements',id);renderStock()}};
async function renderAssets(){if(!$('assetTable'))return;let xs=await all('assets');$('assetTable').innerHTML=table(xs.map(x=>{let annual=Math.max(0,(Number(x.value||0)-Number(x.residual||0))/Math.max(1,Number(x.life||1))),months=Math.max(0,(new Date().getFullYear()-new Date(x.date||today()).getFullYear())*12+(new Date().getMonth()-new Date(x.date||today()).getMonth())),dep=Math.min(Number(x.value||0)-Number(x.residual||0),annual*months/12);return `<tr><td><b>${esc(x.name)}</b><small>${esc(x.date)}</small></td><td>${rupiah(x.value)}</td><td>${rupiah(annual)}</td><td>${rupiah(dep)}</td><td><button class="link" onclick="deleteAsset('${x.id}')">Hapus</button></td></tr>`}),['Aset','Nilai','Penyusutan/tahun','Akumulasi estimasi','Aksi'])}
$('assetAdd')?.addEventListener('click',async()=>{if(!await requirePin('menambah aset'))return;$('assetForm').reset();$('assetDate').value=today();$('assetDialog').showModal()});$('assetSave')?.addEventListener('click',async e=>{e.preventDefault();let value=Number($('assetValue').value)||0,residual=Number($('assetResidual').value)||0,life=Number($('assetLife').value)||0;if(value<=0||life<=0||residual>value)return toast('Periksa nilai aset, residu dan umur manfaat');await put('assets',{id:uid(),name:$('assetName').value.trim(),date:$('assetDate').value,value,life,residual,createdAt:Date.now()});$('assetDialog').close();renderAssets();toast('Aset tersimpan')});window.deleteAsset=async id=>{if(!await requirePin('menghapus aset'))return;if(confirm('Hapus catatan aset?')){await del('assets',id);renderAssets()}};
async function renderDebts(){if(!$('debtTable'))return;let xs=[...(await all('liabilities')).map(x=>({...x,entryType:'debt'})),...(await all('receivables')).map(x=>({...x,entryType:'receivable'}))];let filter=$('debtType')?.value||'all';if(filter!=='all')xs=xs.filter(x=>x.entryType===filter);xs.sort((a,b)=>(a.date||'').localeCompare(b.date||''));$('debtTable').innerHTML=table(xs.map(x=>`<tr><td>${x.entryType==='debt'?'Hutang':'Piutang'}</td><td><b>${esc(x.name)}</b><small>${esc(x.date||'')} · jatuh tempo ${esc(x.due||'—')}</small></td><td>${rupiah(x.amount)}</td><td>${esc(x.note||'')}</td><td><button class="link" onclick="deleteDebt('${x.entryType}','${x.id}')">Hapus</button></td></tr>`),['Jenis','Pihak / Tanggal','Nominal','Keterangan','Aksi'])}
$('debtAdd')?.addEventListener('click',async()=>{if(!await requirePin('menambah hutang/piutang'))return;$('debtForm').reset();$('debtDate').value=today();$('debtDialog').showModal()});$('debtSave')?.addEventListener('click',async e=>{e.preventDefault();let type=$('debtEntryType').value,store=type==='debt'?'liabilities':'receivables';await put(store,{id:uid(),name:$('debtName').value.trim(),amount:Number($('debtAmount').value)||0,date:$('debtDate').value,due:$('debtDue').value,note:$('debtNote').value.trim(),createdAt:Date.now()});$('debtDialog').close();renderDebts();toast('Catatan tersimpan')});$('debtType')?.addEventListener('change',renderDebts);window.deleteDebt=async(type,id)=>{if(!await requirePin('menghapus catatan'))return;if(confirm('Hapus catatan?')){await del(type==='debt'?'liabilities':'receivables',id);renderDebts()}};
Object.assign(window,{editExpense,deleteStockMovement,deleteAsset,deleteDebt});
window.editExpenseType=async encoded=>{let old=decodeURIComponent(encoded);if(!await requirePin('mengubah jenis pengeluaran'))return;let n=prompt('Nama jenis baru',old);if(!n||n.trim()===old)return;n=n.trim();let {s,types,items}=await getExpenseMasters();if(types.includes(n))return toast('Nama jenis sudah ada');types=types.map(x=>x===old?n:x);items[n]=items[old]||[];delete items[old];let g={...(s.expenseGroups||{})};g[n]=g[old]||defaultExpenseGroup(old);delete g[old];await saveExpenseMasters(types,items,{...s,expenseGroups:g});for(let x of await all('expenses'))if(x.type===old)await put('expenses',{...x,type:n});renderExpenseMasters();renderExpenses();toast('Jenis diubah')};
window.deleteExpenseType=async encoded=>{let t=decodeURIComponent(encoded);if(!await requirePin('menghapus jenis pengeluaran'))return;if(!confirm(`Hapus jenis ${t} dari master? Catatan lama dipertahankan.`))return;let {s,types,items}=await getExpenseMasters();types=types.filter(x=>x!==t);delete items[t];await saveExpenseMasters(types,items,s);renderExpenseMasters();toast('Jenis dihapus dari master')};
window.editExpenseMasterItem=async(encodedT,encodedOld)=>{let t=decodeURIComponent(encodedT),old=decodeURIComponent(encodedOld);if(!await requirePin('mengubah item pengeluaran'))return;let n=prompt('Nama item baru',old);if(!n||n.trim()===old)return;n=n.trim();let {s,types,items}=await getExpenseMasters();if((items[t]||[]).includes(n))return toast('Item sudah ada');items[t]=(items[t]||[]).map(x=>x===old?n:x);await saveExpenseMasters(types,items,s);for(let x of await all('expenses'))if(x.type===t&&x.name===old)await put('expenses',{...x,name:n});renderExpenseMasters();renderExpenses();toast('Item diubah')};
window.deleteExpenseMasterItem=async(encodedT,encodedI)=>{let t=decodeURIComponent(encodedT),i=decodeURIComponent(encodedI);if(!await requirePin('menghapus item pengeluaran'))return;if(!confirm(`Hapus item ${i} dari master? Catatan lama dipertahankan.`))return;let {s,types,items}=await getExpenseMasters();items[t]=(items[t]||[]).filter(x=>x!==i);await saveExpenseMasters(types,items,s);renderExpenseMasters();toast('Item dihapus dari master')};
let profitValue='';$('profitReveal')?.addEventListener('click',async()=>{if($('profitReveal').dataset.visible==='1'){$('todayProfit').textContent='••••••';$('profitReveal').textContent='Tampilkan (PIN)';$('profitReveal').dataset.visible='0';return}if(!await requirePin('melihat keuntungan hari ini'))return;$('todayProfit').textContent=profitValue||'Rp0';$('profitReveal').textContent='Sembunyikan';$('profitReveal').dataset.visible='1'});
async function renderFinancialFlow(mode){let tx=(await all('transactions')).filter(x=>x.date>=dateRange().from&&x.date<=dateRange().to),ex=(await all('expenses')).filter(x=>x.date>=dateRange().from&&x.date<=dateRange().to);let cash=mode==='cashbook';let rows=[],days=[...new Set([...tx.map(x=>x.date),...ex.map(x=>x.date)])].sort();for(let d of days){let inTx=tx.filter(x=>x.date===d&&(!cash||['Tunai','Cash'].includes(x.payment))),out=ex.filter(x=>x.date===d&&(!cash||['Tunai','Cash'].includes(x.payment||'Tunai')));rows.push(`<tr><td>${d}</td><td>${rupiah(inTx.reduce((a,x)=>a+x.total,0))}</td><td>${rupiah(out.reduce((a,x)=>a+(Number(x.amount)||0),0))}</td><td><b>${rupiah(inTx.reduce((a,x)=>a+x.total,0)-out.reduce((a,x)=>a+(Number(x.amount)||0),0))}</b></td></tr>`)}$('reportResult').innerHTML=`<p class="muted">${cash?'Buku kas hanya metode Tunai/Cash.':'Arus kas semua metode pembayaran, dihitung dari transaksi yang tercatat.'}</p>`+table(rows,['Tanggal','Pemasukan','Pengeluaran','Selisih'])}
async function renderProfitLoss(){let tx=reportRows,expenses=(await all('expenses')).filter(x=>x.date>=dateRange().from&&x.date<=dateRange().to),sales=tx.reduce((a,x)=>a+Number(x.total||0),0),cogs=tx.reduce((a,x)=>a+x.items.reduce((b,i)=>b+(Number(i.costPrice)||0)*(Number(i.qty)||0),0),0),ex=expenses.reduce((a,x)=>a+(Number(x.amount)||0),0);$('reportResult').innerHTML=table([`<tr><td>Penjualan</td><td>${rupiah(sales)}</td></tr>`,`<tr><td>HPP</td><td>${rupiah(cogs)}</td></tr>`,`<tr><td>Pengeluaran tercatat</td><td>${rupiah(ex)}</td></tr>`,`<tr><td><b>Laba/Rugi estimasi</b></td><td><b>${rupiah(sales-cogs-ex)}</b></td></tr>`],['Komponen','Nilai'])}
async function renderDepreciationReport(){let xs=await all('assets'),rows=xs.map(x=>{let annual=(Number(x.value||0)-Number(x.residual||0))/Math.max(1,Number(x.life||1));return `<tr><td>${esc(x.name)}</td><td>${rupiah(x.value)}</td><td>${Number(x.life||1)} tahun</td><td>${rupiah(annual)}</td></tr>`});$('reportResult').innerHTML=table(rows,['Aset','Nilai perolehan','Umur manfaat','Penyusutan tahunan'])}
$('openingBalanceBtn')?.addEventListener('click',async()=>{if(!await requirePin('mengatur neraca awal'))return;let x=(await all('openingBalance')).find(x=>x.id==='main')||{};$('openingDate').value=x.date||today();$('openingCash').value=x.cash||0;$('openingBank').value=x.bank||0;$('openingNote').value=x.note||'';$('openingBalanceDialog').showModal()});$('openingSave')?.addEventListener('click',async e=>{e.preventDefault();await put('openingBalance',{id:'main',date:$('openingDate').value,cash:Number($('openingCash').value)||0,bank:Number($('openingBank').value)||0,note:$('openingNote').value.trim()});$('openingBalanceDialog').close();toast('Neraca awal tersimpan')});
